@WebServlet("/student")
public class StudentServlet extends HttpServlet {
  protected void doPost(HttpServletRequest rq, HttpServletResponse rs) throws IOException {
    String act = rq.getParameter("action");
    try (Connection c = DriverManager.getConnection("jdbc:mysql://localhost:3306/college","root","root")) {
      if ("add".equals(act)) {
        PreparedStatement p = c.prepareStatement("INSERT INTO student(id,name) VALUES(?,?)");
        p.setInt(1, Integer.parseInt(rq.getParameter("id"))); p.setString(2, rq.getParameter("name")); p.executeUpdate();
      } else if ("delete".equals(act)) {
        PreparedStatement p = c.prepareStatement("DELETE FROM student WHERE id=?");
        p.setInt(1, Integer.parseInt(rq.getParameter("id"))); p.executeUpdate();
      }
    } catch (SQLException e) { throw new IOException(e); }
    rs.sendRedirect("student");
  }
}

