@RestController
@RequestMapping("/students")
public class StudentController {
  private final StudentRepo repo;
  public StudentController(StudentRepo repo){ this.repo = repo; }
  @GetMapping public List<Student> all(){ return repo.findAll(); }
  @GetMapping("/{id}") public ResponseEntity<Student> one(@PathVariable int id){
    return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build()); }
  @PostMapping public ResponseEntity<Student> add(@RequestBody Student s){
    return ResponseEntity.status(201).body(repo.save(s)); }
  @DeleteMapping("/{id}") public ResponseEntity<Void> del(@PathVariable int id){
    repo.deleteById(id); return ResponseEntity.noContent().build(); }
}
